const protonDbCoverSurface = (path) => {
    if (/^\/(?:routes\/)?library\/home(?:\/|$)/.test(path ?? ""))
        return "home";
    if (/^\/(?:routes\/)?library(?:\/(?:collections|tab)(?:\/|$)|\/?$)/.test(path ?? ""))
        return "library";
    return null;
};

